// Drawing helpers.
inline void draw(const uint16_t* data, int w, int h, int x, int y, bool keyed = true) {
  M5.Display.setSwapBytes(true);
  if (keyed) M5.Display.pushImage(x, y, w, h, data, clear); else M5.Display.pushImage(x, y, w, h, data);
  M5.Display.setSwapBytes(false);
}
inline void drawRle(const uint16_t* d, int h, int x0 = 0, int y0 = 0) {
  M5.Display.setSwapBytes(true);
  M5.Display.startWrite();
  for (int y = 0; y < h; ++y) {
    for (int runs = *d++; runs > 0; --runs) {
      const int x = *d++, length = *d++;
      M5.Display.pushImage(x0 + x, y0 + y, length, 1, d);
      d += length;
    }
  }
  M5.Display.endWrite();
  M5.Display.setSwapBytes(false);
}
// Cream text centred on a plaque or banner.
inline void words(const char* text, int cx, int cy, const lgfx::IFont* font, uint32_t color) {
  auto& s = M5.Display;
  s.setFont(font); s.setTextSize(1); s.setTextColor(color); s.setTextDatum(textdatum_t::middle_center);
  s.drawString(text, cx, cy);
  s.setTextDatum(textdatum_t::top_left); s.setFont(&fonts::Font0);
}
